import{bV as e,aL as o,u as i,G as r}from"./chunks/framework.DvBUyM1S.js";const p=JSON.parse('{"title":"通用架构哲学 · 思维框架（可移植版）","description":"","frontmatter":{"id":"PB-20260827-002","type":"playbook","title":"通用架构哲学 · 思维框架（可移植版）","tags":["architecture","design-philosophy","capability-seam","dependency-inversion"],"status":"draft","source":"conversation:2026-08-27","created":"2026-08-27T00:00:00.000Z","updated":"2026-08-27T00:00:00.000Z"},"headers":[],"relativePath":"playbooks/generic-architecture-philosophy.md","filePath":"playbooks/generic-architecture-philosophy.md"}'),l={name:"playbooks/generic-architecture-philosophy.md"};function a(s,t,n,d,h,c){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="通用架构哲学-·-思维框架-可移植版" tabindex="-1">通用架构哲学 · 思维框架（可移植版） <a class="header-anchor" href="#通用架构哲学-·-思维框架-可移植版" aria-label="Permalink to &quot;通用架构哲学 · 思维框架（可移植版）&quot;">​</a></h1><blockquote><p>蒸馏自 DeepSeek Harness 设计哲学，抽掉 Cordis/LLM 专属细节，可在<strong>任意后端/前端项目</strong>复用。完整版 agent skill 存于 <code>deepseek-harness/.agents/skills/generic-architecture-philosophy/</code>。</p></blockquote><h2 id="框架概览" tabindex="-1">框架概览 <a class="header-anchor" href="#框架概览" aria-label="Permalink to &quot;框架概览&quot;">​</a></h2><p>核心一句话：<strong>没有特权的核心，只有组合起来的模块；一切行为挂在文档化的扩展点上，并以可逆转的注册进入系统；可观测状态是唯一真相源。</strong></p><p>三条承重墙：</p><ol><li><strong>模块即架构</strong>：运行时由配置/装配图组合而成。能力来自模块，不是写死在核心循环。改核心循环是 rare event，加模块是常态。</li><li><strong>可观测即记录</strong>：任何影响外部行为或需回放/审计的状态变更，都要进事件流/审计日志。</li><li><strong>显式边界</strong>：部署可变的取舍是显式配置；内部信任类型系统，只在跨信任边界时校验。</li></ol><h2 id="心智模型-9-条" tabindex="-1">心智模型（9 条） <a class="header-anchor" href="#心智模型-9-条" aria-label="Permalink to &quot;心智模型（9 条）&quot;">​</a></h2><ul><li><strong>MM1 无特权核心 / 一切皆模块</strong>：扩展 = 加模块，不是改核心。</li><li><strong>MM2 可逆注册</strong>：路由/监听器/定时任务/连接池都经注册进入，卸载统一释放，返回 disposer。</li><li><strong>MM3 能力缝合三角（依赖反转）</strong>：定义 + 实现 + 消费三角色，缺一无完整能力；分处不同模块当且仅当各自独立演化。</li><li><strong>MM4 可观测 ⟺ 已记录（审计/事件溯源）</strong>：外部可见副作用必须能从事件/审计流重建。</li><li><strong>MM5 事件/钩子是扩展点，中间件必须委托</strong>：拦截器必须显式调用 <code>next()</code>，否则短路。</li><li><strong>MM6 显式优于隐式</strong>：部署可变取舍是配置字段 + 显式 <code>resolve()</code>，不藏 <code>?? default</code>。</li><li><strong>MM7 同进程信类型，边界校验</strong>：内部信类型；只在解析/config/队列/API-DB/文件/网络边界校验。</li><li><strong>MM8 善终优先</strong>：先子后父、await 到静默；正交结果独立上报；异步≠同步。</li><li><strong>MM9 地基优于兼容壳</strong>：无外部消费者时优先做对，不为不存在的消费者提前做兼容。</li></ul><h2 id="决策启发式" tabindex="-1">决策启发式 <a class="header-anchor" href="#决策启发式" aria-label="Permalink to &quot;决策启发式&quot;">​</a></h2><ul><li>加新能力 → 先画 定义/实现/消费 三角；为所有当前 Consumer 设计接口。</li><li>影响外部行为 → 加事件/审计记录，确保可重建。</li><li>改核心循环 → 先确认无扩展点承载；同步文档/ADR。</li><li>可变开关 → 做配置字段，不藏 <code>?? default</code>。</li><li>跨信任边界数据 → 类型化；校验只在边界。</li><li>非平凡改动 → 写 ADR；改了过时行为改其测试。</li></ul><h2 id="张力对比-默认落点" tabindex="-1">张力对比（默认落点） <a class="header-anchor" href="#张力对比-默认落点" aria-label="Permalink to &quot;张力对比（默认落点）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>张力</th><th>落点</th></tr></thead><tbody><tr><td>模块纯度 vs 产品务实</td><td>看演化独立性（MM3）</td></tr><tr><td>静态信任 vs 边界校验</td><td>按边界类型分流（MM7）</td></tr><tr><td>地基 vs 兼容壳</td><td>发布前优先地基（MM9）</td></tr><tr><td>显式 vs 简洁</td><td>部署可变者必显式（MM6）</td></tr><tr><td>模块自由 vs 可观测纪律</td><td>可观测优先（MM4）</td></tr><tr><td>接口集中 vs 消费方自治</td><td>接口为所有 Consumer 设计</td></tr></tbody></table><h2 id="应用工作流-8-步" tabindex="-1">应用工作流（8 步） <a class="header-anchor" href="#应用工作流-8-步" aria-label="Permalink to &quot;应用工作流（8 步）&quot;">​</a></h2><ol><li>归类：能力/扩展点/生命周期/配置？</li><li>找扩展点：查装配配置，无则才改核心并同步文档。</li><li>画三角：列 定义/实现/消费，确认 Consumer 证据。</li><li>查可观测性：外部可见？加事件/审计。</li><li>定边界：可变→配置+resolve；跨边界→类型化；校验只在边界。</li><li>想善终：先子后父、await 到静默。</li><li>验世界：真实入口 + 集成/端到端覆盖外部行为 + 验证副作用。</li><li>对称自查：平行值是否对称？</li></ol><h2 id="诚实边界" tabindex="-1">诚实边界 <a class="header-anchor" href="#诚实边界" aria-label="Permalink to &quot;诚实边界&quot;">​</a></h2><ul><li>框架无关，不绑语言/框架；动态语言把 MM7&quot;信任类型&quot;换成&quot;信任内部契约&quot;。</li><li>给方向不给具体 API；以项目现状为准。</li><li>是 <code>harness-design-philosophy</code> 的可移植兄弟版（去 Cordis/LLM 专属）。</li></ul>',16)])])}const g=e(l,[["render",a]]);export{p as __pageData,g as default};
